import csv
from collections import defaultdict
from datetime import datetime

# Load stops
def load_stops(path):
    stops = {}
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            stops[row['stop_id']] = {
                'stop_id': row['stop_id'],
                'stop_name': row['stop_name'],
                'stop_lat': float(row['stop_lat']),
                'stop_lon': float(row['stop_lon'])
            }
    return stops

# Load trip_id, stop_id, departure_time from stop_times
def load_stop_times(path):
    trips = []
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            trips.append({
                'trip_id': row['trip_id'],
                'stop_id': row['stop_id'],
                'departure_time': row['departure_time']
            })
    return trips

# Load trips from gtfs zip
def load_trips(path):
    trips = []
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            trips.append({
                'route_id': row['route_id'],
                'service_id': row['service_id'],
                'trip_id': row['trip_id'],
                'shape_id': row['shape_id']
            })
    return trips

# Join trip_id with trips to get route_id
trip_to_route = {}
for trip in load_trips('inputs/gtfs/sample_city_gtfs.zip'):
    trip_to_route[trip['trip_id']] = trip['route_id']

# Load stops
def load_stops(path):
    stops = {}
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            stops[row['stop_id']] = {
                'stop_id': row['stop_id'],
                'stop_name': row['stop_name'],
                'stop_lat': float(row['stop_lat']),
                'stop_lon': float(row['stop_lon'])
            }
    return stops

# Load stop_times
def load_stop_times(path):
    trips = []
    with open(path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            trips.append({
                'trip_id': row['trip_id'],
                'stop_id': row['stop_id'],
                'departure_time': row['departure_time']
            })
    return trips

# Main processing
def main():
    stops = load_stops('outputs/t05_clean_stops.csv')
    stop_times = load_stop_times('outputs/t05_clean_stop_times.csv')

    # Join stop_times with trips to get route_id
    for trip in stop_times:
        trip['route_id'] = trip_to_route.get(trip['trip_id'], None)

    # Group by stop_id
    stop_data = defaultdict(lambda: {
        'n_departures': 0,
        'n_routes': set(),
        'first_departure': None,
        'last_departure': None
    })

    for trip in stop_times:
        stop_id = trip['stop_id']
        if stop_id in stops:
            stop_data[stop_id]['n_departures'] += 1
            stop_data[stop_id]['n_routes'].add(trip['route_id'])

            dep_time = datetime.strptime(trip['departure_time'], '%H:%M:%S')

            if stop_data[stop_id]['first_departure'] is None or dep_time < stop_data[stop_id]['first_departure']:
                stop_data[stop_id]['first_departure'] = dep_time
            if stop_data[stop_id]['last_departure'] is None or dep_time > stop_data[stop_id]['last_departure']:
                stop_data[stop_id]['last_departure'] = dep_time

    # Write output
    with open('outputs/t06_stop_service_intensity.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['stop_id', 'stop_name', 'stop_lat', 'stop_lon', 'n_departures', 'n_routes', 'first_departure', 'last_departure'])

        for stop_id, data in sorted(stop_data.items()):
            stop = stops[stop_id]
            writer.writerow([
                stop['stop_id'],
                stop['stop_name'],
                stop['stop_lat'],
                stop['stop_lon'],
                data['n_departures'],
                len(data['n_routes']),
                stop_data[stop_id]['first_departure'],
                stop_data[stop_id]['last_departure']
            ])

if __name__ == '__main__':
    main()
    print("Done!")

main()

